package com.logatron.processor.consume;
import com.fasterxml.jackson.databind.ObjectMapper;import com.logatron.contracts.ingestion.*;import com.logatron.processor.deduplicate.DuplicateTracker;import com.logatron.processor.dlq.DeadLetterFactory;import com.logatron.processor.enrich.*;import com.logatron.processor.parse.*;import com.logatron.processor.protect.SensitiveDataMasker;import com.logatron.processor.validate.*;import org.springframework.stereotype.Component;import java.util.List;
@Component public class ProcessorPipeline {private final ObjectMapper json;private final EnvelopeValidator envelopes;private final MetadataResolver metadata;private final List<LogParser> parsers;private final SensitiveDataMasker masker;private final CanonicalEventFactory factory;private final CanonicalValidator canonical;private final DuplicateTracker duplicates;private final DeadLetterFactory dlq;public ProcessorPipeline(ObjectMapper json,EnvelopeValidator envelopes,MetadataResolver metadata,List<LogParser> parsers,SensitiveDataMasker masker,CanonicalEventFactory factory,CanonicalValidator canonical,DuplicateTracker duplicates,DeadLetterFactory dlq){this.json=json;this.envelopes=envelopes;this.metadata=metadata;this.parsers=parsers;this.masker=masker;this.factory=factory;this.canonical=canonical;this.duplicates=duplicates;this.dlq=dlq;}public ProcessingOutcome process(String value){RawLogEnvelope raw=null;try{raw=json.readValue(value,RawLogEnvelope.class);envelopes.validate(raw);SourceMetadata source=metadata.resolve(raw);RawLogEnvelope protectedRaw=new RawLogEnvelope(raw.schemaVersion(),raw.eventId(),raw.observedTimestamp(),raw.collector(),raw.resource(),raw.source(),masker.mask(raw.payload()),raw.attributes());LogParser parser=parsers.stream().filter(p->p.supports(source.parserProfile())).findFirst().orElseThrow(()->new ProcessingException("PARSER_NOT_FOUND","No parser supports the registered profile"));CanonicalLogEvent event=factory.create(protectedRaw,parser.parse(protectedRaw,source.timestampZone()),source);canonical.validate(event);return ProcessingOutcome.event(event,duplicates.seen(event.eventId()));}catch(Exception failure){return ProcessingOutcome.dead(dlq.create(value,raw,"PROCESS",failure,0));}}}